var frontmatter = {
	"title": "全局函数 SfGFunc",
	"description": "自定义全局函数注册与调用"
};
var _markdown = "\n\n`sa` · 扩展 `SAMPFUNCS` · 仅 SA-MP；需 SAMPFUNCS\n\n共 6 条。调用见 [Lua](/docs/cleo/syntax) / [Redux](/docs/cleo/syntax-redux)。\n\n## 注册 / 调用 / 返回 [#注册--调用--返回]\n\n<Opcode id=\"0C34\" name=\"SF_REGISTER_CUSTOM_GLOBAL_FUNCTION\" member=\"SfGFunc.Register\">\n  注册自定义全局函数名，供其他脚本用 `SF_CALL_CUSTOM_GLOBAL_FUNCTION` 调用。用在 `if` 里。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0C34 SF_REGISTER_CUSTOM_GLOBAL_FUNCTION\n      in: name, label\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      if sfRegisterCustomGlobalFunction(name, label) then\n      end\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      if (SfGFunc.Register(name, label)) {\n      }\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n<Opcode id=\"0C35\" name=\"SF_CALL_CUSTOM_GLOBAL_FUNCTION\" member=\"SfGFunc.Call\">\n  按名称调用已注册的自定义全局函数。用在 `if` 里。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0C35 SF_CALL_CUSTOM_GLOBAL_FUNCTION\n      in: name, numArgs, args\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      if sfCallCustomGlobalFunction(name, numArgs, args) then\n      end\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      if (SfGFunc.Call(name, numArgs, args)) {\n      }\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n<Opcode id=\"0C36\" name=\"SF_CUSTOM_GLOBAL_FUNCTION_RETURN\" member=\"SfGFunc.Return\">\n  从自定义全局函数返回到调用后下一条指令，可附带返回值。用在 `if` 里。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0C36 SF_CUSTOM_GLOBAL_FUNCTION_RETURN\n      in: numRet, retParams\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      if sfCustomGlobalFunctionReturn(numRet, retParams) then\n      end\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      if (SfGFunc.Return(numRet, retParams)) {\n      }\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 查询 / 注销 [#查询--注销]\n\n<Opcode id=\"0C37\" name=\"SF_IS_CUSTOM_GLOBAL_FUNCTION_REGISTERED\" member=\"SfGFunc.IsRegistered\">\n  若指定名称已注册为自定义全局函数则为真。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0C37 SF_IS_CUSTOM_GLOBAL_FUNCTION_REGISTERED\n      in: name\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      if sfIsCustomGlobalFunctionRegistered(name) then\n      end\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      if (SfGFunc.IsRegistered(name)) {\n      }\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n<Opcode id=\"0C38\" name=\"SF_CUSTOM_GLOBAL_FUNCTION_GET_ORIGIN\" member=\"SfGFunc.GetOrigin\">\n  返回指定名称自定义全局函数的来源信息。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0C38 SF_CUSTOM_GLOBAL_FUNCTION_GET_ORIGIN\n      in: name\n      out: hostThreadAddress, functionAddress\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      local hostThreadAddress, functionAddress = sfCustomGlobalFunctionGetOrigin(name)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      const { hostThreadAddress, functionAddress } = SfGFunc.GetOrigin(name)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n<Opcode id=\"0C39\" name=\"SF_UNREGISTER_CUSTOM_GLOBAL_FUNCTION\" member=\"SfGFunc.Unregister\">\n  注销已注册的自定义全局函数，名称可再注册。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0C39 SF_UNREGISTER_CUSTOM_GLOBAL_FUNCTION\n      in: name\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      sfUnregisterCustomGlobalFunction(name)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      SfGFunc.Unregister(name)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n";
